-- Read-only metadata inventory. Save results privately; contains internal IDs and locators.
select jsonb_build_object(
'exams',(select jsonb_agg(jsonb_build_object('id',id,'slug',slug,'name',name) order by id) from exams),
'users',(select jsonb_agg(jsonb_build_object('id',u.id,'is_active',u.is_active,'focus',f.exam_slug,'observed_exam_ids',(select coalesce(jsonb_agg(distinct exam_id),'[]'::jsonb) from (select exam_id from exam_targets where user_id=u.id union select exam_id from mock_attempts where user_id=u.id union select q.exam_id from question_attempts a join questions q on q.id=a.question_id where a.user_id=u.id) observed)) order by u.id) from users u left join user_exam_focus f on f.user_id=u.id),
'sources',(select jsonb_agg(to_jsonb(g)) from (select exam_id,source_type,source_reference,jsonb_agg(id order by id) as question_ids,count(*) as count from questions group by exam_id,source_type,source_reference order by exam_id,source_type,source_reference) g),
'resources',(select jsonb_agg(to_jsonb(r)) from (select 'lesson' as kind,l.id,t.id as topic_id,s.exam_id,null::text as recorded_source_notes from lessons l join topics t on t.id=l.topic_id join subjects s on s.id=t.subject_id union all select 'archetype',a.id,t.id,s.exam_id,a.source_notes from question_archetypes a join topics t on t.id=a.topic_id join subjects s on s.id=t.subject_id union all select 'flashcard',f.id,t.id,s.exam_id,null::text from flashcards f join topics t on t.id=f.topic_id join subjects s on s.id=t.subject_id) r),
'lesson_blocks',(select jsonb_agg(jsonb_build_object('id',id,'lesson_id',lesson_id) order by id) from lesson_blocks),
'assets',(select jsonb_agg(to_jsonb(a)) from (select question_image_url as asset_url,jsonb_agg(id order by id) as question_ids,'stem' as usage from questions where nullif(question_image_url,'') is not null group by question_image_url union all select image_url,jsonb_agg(distinct question_id),'option' from question_options where nullif(image_url,'') is not null group by image_url) a),
'baseline',jsonb_build_object('questions',(select count(*) from questions),'question_id_digest',(select md5(string_agg(id::text,',' order by id)) from questions),'question_attempts',(select count(*) from question_attempts),'mock_attempts',(select count(*) from mock_attempts),'mock_responses',(select count(*) from mock_attempt_questions),'active_mocks',(select count(*) from mock_attempts where status='in_progress'))
) as inventory;
